{"description":"Sum snowfall per station in CSV","command":"python3 - <<'EOF'
import csv
from collections import defaultdict
rows=list(csv.DictReader(open('/workspace/fetched/yow_daily.csv')))
tot=defaultdict(float); n=defaultdict(int); mx={}
for r in rows:
    s=r['STN_ID']; v=r['TOTAL_SNOW']
    if v not in ('','NA'):
        fv=float(v)
        tot[s]+=fv; n[s]+=1
        if fv>mx.get(s,(0,''))[0]: mx[s]=(fv,r['LOCAL_DATE'])
for s in sorted(tot):
    print(s, 'days=',n[s], 'total_mm=',tot[s], 'max=',mx[s])
print('rows:',len(rows))
EOF"}

