import re
html=open('/workspace/fetched/nov2025.html',encoding='utf-8').read()
rows=re.findall(r'<tr[^>]*>(.*?)</tr>', html, re.S)
tot=0.0; days=[]
for r in rows:
    cells=[re.sub(r'<[^>]+>','',c).strip().replace('&nbsp;','') for c in re.findall(r'<t[dh][^>]*>(.*?)</t[dh]>', r, re.S)]
    if len(cells)>=8 and re.fullmatch(r'\d{1,2}', cells[0]):
        v=cells[7]
        days.append((cells[0],v))
        if re.fullmatch(r'[\d.]+', v): tot+=float(v)
print('daily snow (day, value cm):')
for d,v in days: print(d, repr(v))
print('sum of numeric daily values:', tot)
EOF"}

