import re, glob
def parse(path):
    html=open(path,encoding='utf-8').read()
    rows=re.findall(r'<tr[^>]*>(.*?)</tr>', html, re.S)
    tot=0.0; ok=True
    for r in rows:
        cells=[re.sub(r'<[^>]+>','',c).strip().replace('&nbsp;','') for c in re.findall(r'<t[dh][^>]*>(.*?)</t[dh]>', r, re.S)]
        if len(cells)>=8 and re.fullmatch(r'\d{1,2}', cells[0]):
            v=cells[7]
            if not re.fullmatch(r'[\d.]+', v): ok=False
            else: tot+=float(v)
    return tot, ok

months={'nov2025.html':'2025-11'}
for f in sorted(glob.glob('/workspace/fetched/m_*.html')):
    name=f.split('/')[-1][2:-5]  # e.g. 2025_12
    months[f]=name.replace('_','-')
total=0
for f,m in months.items():
    t,ok=parse(f)
    total+=t
    print(m, round(t,1), 'cm', '' if ok else '(contains non-numeric days!)')
print('TOTAL:', round(total,1), 'cm =', round(total*10,1), 'mm')
EOF"}

